        cases = []
        def walk(node):
            if node.get("nodeType") == "Test Case":
                cases.append(node)
            for child in node.get("children", []):
                walk(child)
        for node in tests.get("testNodes", []):
            walk(node)
        for case in cases:
            details = tool("test-details", "--test-id", case.get("nodeIdentifier", ""),
                           "--path", str(bundle))
