    def per_simulator(case):
        """A case's result on each simulator it ran on, or its one result."""
        devices = [child for child in case.get("children", []) if child.get("nodeType") == "Device"]
        if not devices:
            return str(case.get("result"))
        return "; ".join(f"{device.get('name')}: {device.get('result')}" for device in devices)
