        if isinstance(node, list):
            for item in node:
                yield from measured(item, device)
        elif isinstance(node, dict):
            if isinstance(node.get("device"), dict):
                device = node["device"].get("deviceName", device)
            values = node.get("measurements")
            if isinstance(values, list) and values and all(
                    isinstance(value, (int, float)) for value in values):
                name = " ".join(str(node.get(key, "")) for key in ("displayName", "identifier"))
                yield device, name.strip(), node.get("unitOfMeasurement", ""), values
            for key, value in node.items():
                if key != "measurements":
                    yield from measured(value, device)
