            elif not sessions or not found:
                continue
            elif "Test Suite 'Selected tests' started at" in line:
                sessions[-1].setdefault("suite", found.group(0))
            elif "Start Test at" in line:
                sessions[-1].setdefault("test", found.group(0))
            elif "IDELaunchParametersSnapshot: no debugger version" in line:
                if "test" in sessions[-1]:
