        records = json.loads(path.read_text()) if path.is_file() else []
        for simulator in simulators:
            record = next((r for r in records if r.get("simulator") == simulator), {})
            for phase, what in (("bootstatus", "boot wait"), ("launch", "launch"),
                                ("terminate", "end")):
                done = record.get("phases", {}).get(phase) or {}
                value = done.get("outcome", "not measured")
                if "seconds" in done:
                    value = f"{done['seconds']:g} s, {value}"
                if phase == "bootstatus" and record:
                    value += f", {record.get('state') or 'unknown'} before"
                rows.append((f"{title} warm {what}, {simulator}", value))
    def runner_rows(label, title):
        """Each simulator's UI test runner bootstrap and first-launch gap, read from the step's
        console in destination order by the stamps its lines carry (SPEC-339 R16)."""
        if elsewhere(label):
            for simulator in simulators:
                rows.append((f"{title} runner bootstrap, {simulator}", elsewhere(label)))
                rows.append((f"{title} first-launch gap, {simulator}", elsewhere(label)))
            return
        stamp = re.compile(r"\d{4}-\d\d-\d\d \d\d:\d\d:\d\d\.\d+")
        def at(text):
            return datetime.datetime.strptime(text, "%Y-%m-%d %H:%M:%S.%f")
        def seconds(session, start, end):
            if not (session.get(start) and session.get(end)):
                return None
            return f"{(at(session[end]) - at(session[start])).total_seconds():.1f} s"
        path = report / f"{label}-console.log"
        lines = path.read_text(errors="replace").splitlines() if path.is_file() else []
        sessions = []
        for line in lines:
            found = stamp.search(line)
            if re.search(r"-Runner\[\d+:\d+\] \[Default\] Running tests\.\.\.", line):
                sessions.append({"runner": found.group(0) if found else None})
            elif not sessions or not found:
                continue
            elif "Test Suite 'Selected tests' started at" in line:
                sessions[-1].setdefault("suite", found.group(0))
            elif "Start Test at" in line:
                sessions[-1].setdefault("test", found.group(0))
            elif "IDELaunchParametersSnapshot: no debugger version" in line:
                if "test" in sessions[-1]:
                    sessions[-1].setdefault("launch", found.group(0))
        for index, simulator in enumerate(simulators):
            if len(sessions) != len(simulators):
                bootstrap = gap = (f"not measured ({len(sessions)} runner sessions for "
                                   f"{len(simulators)} simulators)")
            else:
                session = sessions[index]
                bootstrap = seconds(session, "runner", "suite") or (
                    "the runner reached no test" if session.get("runner") else "not measured")
                gap = seconds(session, "test", "launch") or "not measured"
            rows.append((f"{title} runner bootstrap, {simulator}", bootstrap))
            rows.append((f"{title} first-launch gap, {simulator}", gap))
    warm_rows("debug", "Debug")
    runner_rows("debug", "Debug")
    warm_rows("release", "Release")
    runner_rows("release", "Release")
    def end_rows(label, title):
        """Each simulator's longest XCTest end of an earlier instance at a launch, read from
        the step's console in destination order by XCTest's own seconds (SPEC-339 R16)."""
        if elsewhere(label):
            rows.extend((f"{title} longest end, {simulator}", elsewhere(label))
                        for simulator in simulators)
            return
        path = report / f"{label}-console.log"
        lines = path.read_text(errors="replace").splitlines() if path.is_file() else []
        sessions, pending = [], None
        for line in lines:
            if re.search(r"-Runner\[\d+:\d+\] \[Default\] Running tests\.\.\.", line):
                sessions.append([])
                pending = None
                continue
            activity = re.match(r"\s*t =\s+(\d+(?:\.\d+)?)s\s+(.*)", line)
            if not sessions or not activity:
                continue
            at = float(activity.group(1))
            if pending is not None and at >= pending:
                sessions[-1].append(at - pending)
            pending = None
            if re.fullmatch(r"Terminate \S+:\d+", activity.group(2).strip()):
                pending = at
        for index, simulator in enumerate(simulators):
            if len(sessions) != len(simulators):
                value = (f"not measured ({len(sessions)} runner sessions for "
                         f"{len(simulators)} simulators)")
            elif not sessions[index]:
                value = "no end in the session"
            else:
                ends = sessions[index]
                value = f"{max(ends):.1f} s, the longest end of {len(ends)}"
            rows.append((f"{title} longest end, {simulator}", value))
    end_rows("debug", "Debug")
    end_rows("release", "Release")
